[[nodiscard]] std::optional<Grant> authorize(const Subject& s, Op op, const Resource& r)
{
    auto it = grants_.find(Key{s.id, op, r.id});   // explicit grants only
    if (it == grants_.end()) return std::nullopt;  // no grant -> deny
    return *it;
}
auto grant = authorize(subject, Op::Read, order);
if (!grant) return denied("no grant for read");    // fail closed
return order.read(*grant);
